using System.Diagnostics;
using System.Net;
using System.Net.Http.Headers;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using System.Threading.Channels;
using Home.NativeTests;
using HomeServer.Core;
using HomeServer.Gaming;
using HomeServer.Infrastructure;

static class BasicStreamProbe
{
    public static async Task<object> RunAsync(HomePaths runtime,NativeRuntimeProfile host,NativeRuntimeFile binary,NativeRuntimeFile info,string system,byte[] original,string root,string ffmpeg)
    {
        using var hostLock=new FileStream(Path.Combine(runtime.State,"games","native-host.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);
        var ports=new[]{62401,62402,62403,62404,62405,62406,62407,62408,62420,62421,62422,62423};var ip=IPGlobalProperties.GetIPGlobalProperties();if(ip.GetActiveUdpListeners().Any(endpoint=>ports.Contains(endpoint.Port))||ip.GetActiveTcpListeners().Any(endpoint=>ports.Contains(endpoint.Port)))throw new InvalidOperationException("An active game owns diagnostic ports; it was not disturbed.");
        var profile=new NativeGpuRuntime(runtime).Verify();var directory=AppFiles.DirectoryIn(root,"streaming");var id=NativeSystems.Require(system).Core;var extension=system switch{"snes"=>"sfc","megadrive"=>"md","ps1"=>"exe",_=>system};
        var config=RetroArchHostConfiguration.CreatePrivateHost(directory,62420,62406,null);await File.WriteAllTextAsync(Path.Combine(directory,"retroarch.cfg"),config);await File.WriteAllTextAsync(Path.Combine(directory,"core-options.cfg"),id=="mgba"?RetroArchHostConfiguration.CoreOptions+(system=="gb"?"mgba_gb_colors = \"Grayscale\"\n":""):"");await File.WriteAllTextAsync(Path.Combine(directory,"record.cfg"),RetroArchHostConfiguration.Recording+RetroArchHostConfiguration.LowDelayMux);
        var core=Path.Combine(directory,"cores",id+"_libretro.dll");File.Copy(binary.Path,core);File.Copy(info.Path,Path.Combine(directory,"info",id+"_libretro.info"));var game=Path.Combine(directory,"game."+extension);await File.WriteAllBytesAsync(game,original);
        var secret=Guid.NewGuid().ToString("N")+Guid.NewGuid().ToString("N");await File.WriteAllTextAsync(Path.Combine(directory,"mediamtx.yml"),MediaMtxGameConfiguration.Create("original-basic",secret,62407,62403,62404,62405));
        using var budget=new CancellationTokenSource(TimeSpan.FromSeconds(45));var token=budget.Token;long packetCount=0,pixelCount=0;var lastColor=(R:(byte)0,G:(byte)0);var phase="startup";
        using var media=MediaProcess.Start(host.MediaMtx.Path,[Path.Combine(directory,"mediamtx.yml")],workingDirectory:directory);var mediaError=MediaProcess.ReadErrorTailAsync(media.StandardError);var mediaOut=MediaProcess.ReadErrorTailAsync(media.StandardOutput);
        using var incoming=new UdpClient(new IPEndPoint(IPAddress.Loopback,62402));using var sender=new UdpClient();var packets=Task.Run(async()=>{try{while(true){var packet=await incoming.ReceiveAsync(token);Interlocked.Increment(ref packetCount);await sender.SendAsync(packet.Buffer,new IPEndPoint(IPAddress.Loopback,62407),token);await sender.SendAsync(packet.Buffer,new IPEndPoint(IPAddress.Loopback,62408),token);}}catch(OperationCanceledException){}},CancellationToken.None);
        // Diagnostic decoder only: allow SPS/geometry discovery. This is not a browser or a latency benchmark.
        using var decoder=MediaProcess.Start(ffmpeg,["-v","warning","-flags","low_delay","-threads","1","-probesize","5000000","-analyzeduration","5000000","-i","udp://127.0.0.1:62408?fifo_size=512&overrun_nonfatal=1","-an","-vf","format=rgb24,crop=1:1:iw/2:ih/2","-fps_mode","passthrough","-f","rawvideo","-pix_fmt","rgb24","pipe:1"],workingDirectory:directory);var decoderError=MediaProcess.ReadErrorTailAsync(decoder.StandardError);var colors=Channel.CreateBounded<(byte R,byte G)>(new BoundedChannelOptions(256){FullMode=BoundedChannelFullMode.DropOldest,SingleReader=true,SingleWriter=true});var pixels=Task.Run(async()=>{var pixel=new byte[3];try{while(true){await decoder.StandardOutput.BaseStream.ReadExactlyAsync(pixel,token);colors.Writer.TryWrite((pixel[0],pixel[1]));}}catch(Exception error)when(error is OperationCanceledException or EndOfStreamException){colors.Writer.TryComplete();}},CancellationToken.None);
        NativeGpuProcess? engine=null;
        try
        {
            engine=NativeGpuProcess.Start(profile.Frontend.Path,["--verbose","--config",Path.Combine(directory,"retroarch.cfg"),"-L",core,"--record",RetroArchHostConfiguration.LocalMpegTs(62402),"--recordconfig",Path.Combine(directory,"record.cfg"),game],directory);
            await using var control=new RetroArchControl(engine.Process,62406);for(var i=0;i<150&&!IPGlobalProperties.GetIPGlobalProperties().GetActiveUdpListeners().Any(endpoint=>endpoint.Port==62406);i++){if(engine.Process.HasExited)throw new InvalidDataException(await engine.ReadLogAfterExitAsync(engine.ErrorLog));await Task.Delay(20,token);}
            await control.StatusAsync(token);var options=await control.CoreOptionsAsync(token);if(system=="gb"){var palette=options.Single(option=>option.Key=="mgba_gb_colors");await control.SetCoreOptionAsync(palette.Index,Array.IndexOf(palette.Values,"Grayscale"),token);}var controllers=await control.ControllersAsync(token);if(system=="megadrive"){var threeButton=controllers[0].Items.Single(item=>item.Name=="MD Joypad 3 Button");await control.SetControllerAsync(0,threeButton.Id,token);}await File.WriteAllTextAsync(Path.Combine(directory,"effective-core-options.json"),JsonSerializer.Serialize(await control.CoreOptionsAsync(token)));await File.WriteAllTextAsync(Path.Combine(directory,"controllers.json"),JsonSerializer.Serialize(await control.ControllersAsync(token)));await control.EnablePacedHeadlessModeAsync(token);using var pad=new UdpClient();pad.Connect(IPAddress.Loopback,62420);phase="released";await WaitColor(false);
            await pad.SendAsync(RetroPadProtocol.Button(8,true),token);await WaitColor(true);await Task.Delay(120,token);await control.SetPausedAsync(true,token);await control.SaveStateAsync(token);var state=Path.Combine(directory,"saves","game.state");for(var i=0;i<100&&!File.Exists(state);i++)await Task.Delay(20,token);if(!File.Exists(state)||new FileInfo(state).Length==0)throw new InvalidDataException("Actual frontend state was not produced.");
            await pad.SendAsync(RetroPadProtocol.Button(8,false),token);await control.SetPausedAsync(false,token);await WaitColor(false);await control.SetPausedAsync(true,token);await control.LoadStateAsync(token);await control.SetPausedAsync(true,token);
            using var client=new HttpClient(new SocketsHttpHandler{UseProxy=false,UseCookies=false,AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(5)};client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes("home-native:"+secret)));using var body=new StringContent(SyntheticWhep.Offer(),Encoding.UTF8,"application/sdp");using var response=await client.PostAsync("http://127.0.0.1:62403/original-basic/whep",body,token);var answer=await response.Content.ReadAsStringAsync(token);if((int)response.StatusCode!=201||!answer.Contains("H264")||!answer.Contains("opus"))throw new InvalidDataException("Actual basic-core H264/Opus source did not negotiate.");
            if(response.Headers.Location is{} location){using var removed=await client.DeleteAsync(new Uri(new Uri("http://127.0.0.1:62403"),location),token);}
            await control.QuitAsync(token);await engine.Process.WaitForExitAsync(token);
            var snapshots=new NativeSaveSnapshots(new HomePaths(Path.Combine(directory,"managed"),Path.Combine(directory,"thumbnails"),null));var manifest=await snapshots.PublishAsync("fixture-owner","rom-fixture","native-fixture",Path.Combine(directory,"saves"),token);var restored=AppFiles.DirectoryIn(directory,"restored");if(!await snapshots.RestoreAsync(new(1,new(){{"native-save.json",manifest}},"native-fixture"),"fixture-owner","rom-fixture","native-fixture",restored,token))throw new InvalidDataException("Actual frontend snapshot did not restore.");
            var writtenState=await File.ReadAllBytesAsync(state,token);var restoredState=await File.ReadAllBytesAsync(Path.Combine(restored,"game.state"),token);if(!writtenState.SequenceEqual(restoredState))throw new InvalidDataException("Actual frontend state snapshot bytes changed.");
            return new{frontendSha256=profile.Frontend.Sha256,actualEncodedInputTransition=true,whepStatus=201,h264Opus=true,frontendStateBytes=new FileInfo(state).Length,frontendStateSnapshotRestored=true,userRomLaunched=false,browserDecoded=false};
            async Task WaitColor(bool pressed){phase=pressed?"pressed":"released";while(await colors.Reader.WaitToReadAsync(token))while(colors.Reader.TryRead(out var color)){lastColor=color;pixelCount++;if(system=="gb"?(pressed?color.R<80:color.R>180):(pressed?color.R>color.G+30:color.G>color.R+30))return;}throw new InvalidDataException("Actual encoded original framebuffer transition missing.");}
        }
        catch(OperationCanceledException failure){throw new InvalidDataException($"Original {system} stream phase {phase} timed out; packets={packetCount}, decodedPixels={pixelCount}, lastPixel={lastColor}.",failure);}
        finally{engine?.Dispose();MediaProcess.Kill(media);MediaProcess.Kill(decoder);budget.Cancel();await media.WaitForExitAsync(CancellationToken.None);await decoder.WaitForExitAsync(CancellationToken.None);await pixels;await packets;await File.WriteAllTextAsync(Path.Combine(directory,"media.log"),(await mediaOut)+(await mediaError));await File.WriteAllTextAsync(Path.Combine(directory,"decoder.log"),await decoderError);}
    }
}
